CREATE OR REPLACE FUNCTION public.mem_segments(_student uuid) RETURNS TABLE(start_ayah integer,end_ayah integer,source text,source_label text,recorded_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT x.start_ayah,x.end_ayah,'recitation','تسميع يومي',r.created_at FROM public.recitation_records r CROSS JOIN LATERAL public.mem_segment(r.memorized_from,r.memorized_to)x WHERE r.student_id=_student AND x.start_ayah IS NOT NULL UNION ALL SELECT x.start_ayah,x.end_ayah,'annual_plan','محفوظ سابق في الخطة',p.updated_at FROM public.student_annual_plans p CROSS JOIN LATERAL jsonb_array_elements(coalesce(p.previous_memorized_ranges,'[]'::jsonb))g CROSS JOIN LATERAL public.mem_segment(g->>'from',g->>'to')x WHERE p.student_id=_student AND x.start_ayah IS NOT NULL UNION ALL SELECT x.start_ayah,x.end_ayah,'annual_plan','محفوظ سابق في الخطة',p.updated_at FROM public.student_annual_plans p CROSS JOIN LATERAL public.mem_segment(p.previous_memorized_from,p.previous_memorized_to)x WHERE p.student_id=_student AND coalesce(jsonb_array_length(p.previous_memorized_ranges),0)=0 AND x.start_ayah IS NOT NULL UNION ALL SELECT x.start_ayah,x.end_ayah,'madarij','سجل مدارج',d.created_at FROM public.madarij_daily_progress d CROSS JOIN LATERAL regexp_match(coalesce(d.memorization,''),'^(.+?)\s*[-–—]\s*(.+)$')m CROSS JOIN LATERAL public.mem_segment(m[1],m[2])x WHERE d.student_id=_student AND x.start_ayah IS NOT NULL UNION ALL SELECT r.start_ayah,r.end_ayah,'manual','استكمال موثق من ملف الطالب',r.created_at FROM public.student_memorization_ranges r WHERE r.student_id=_student AND r.active $$;